import os
import tempfile
import pytest
from envcfg import load, EnvConfigError


def test_defaults_only():
    cfg = load({"a": 1, "b": {"c": 2}})
    assert cfg == {"a": 1, "b": {"c": 2}}


def test_toml_overrides_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b'a = 42\n')
        path = f.name
    try:
        cfg = load({"a": 1}, toml_path=path)
        assert cfg == {"a": 42}
    finally:
        os.unlink(path)


def test_partial_toml_keeps_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b'a = 42\n')
        path = f.name
    try:
        cfg = load({"a": 1, "b": 2}, toml_path=path)
        assert cfg == {"a": 42, "b": 2}
    finally:
        os.unlink(path)


def test_missing_toml_file_ignored():
    cfg = load({"a": 1}, toml_path="/nonexistent.toml")
    assert cfg == {"a": 1}


def test_env_overrides_toml():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b'a = 1\n')
        path = f.name
    try:
        os.environ["APP__A"] = "2"
        cfg = load({"a": 0}, toml_path=path, prefix="APP")
        assert cfg == {"a": 2}
    finally:
        os.environ.pop("APP__A", None)


def test_nested_env_with_prefix():
    os.environ["APP__SERVER__PORT"] = "8080"
    cfg = load({"server": {"port": 80}}, prefix="APP")
    assert cfg == {"server": {"port": 8080}}
    os.environ.pop("APP__SERVER__PORT", None)


def test_int_coercion():
    os.environ["APP__X"] = "123"
    cfg = load({"x": 0}, prefix="APP")
    assert cfg == {"x": 123}
    os.environ.pop("APP__X", None)


def test_float_coercion():
    os.environ["APP__Y"] = "3.14"
    cfg = load({"y": 0.0}, prefix="APP")
    assert cfg == {"y": 3.14}
    os.environ.pop("APP__Y", None)


def test_bool_coercion_true():
    os.environ["APP__Z"] = "yes"
    cfg = load({"z": False}, prefix="APP")
    assert cfg == {"z": True}
    os.environ.pop("APP__Z", None)


